#include <iostream>
#include <string>

void printBox(const std::string& word) {
    std::string border(word.size() + 4, '*');
    std::cout << border << '\n';
    std::cout << "* " << word << " *\n";
    std::cout << border << '\n';
}

int main() {
    std::string word;
    std::cin >> word;
    printBox(word);
    return 0;
}

