go.solution:
package main

import (
	"fmt"
	"strings"
)

func printBox(word string) {
	border := strings.Repeat("*", len(word)+4)
	fmt.Println(border)
	fmt.Printf("* %s *\n", word)
	fmt.Println(border)
}

func main() {
	var word string
	fmt.Scan(&word)
	printBox(word)
}

